def test_single_and_additive():
    assert roman_to_int("I") == 1
    assert roman_to_int("III") == 3
    assert roman_to_int("VI") == 6
    assert roman_to_int("XV") == 15
    assert roman_to_int("MDC") == 1600


def test_subtractive_iv():
    assert roman_to_int("IV") == 4


def test_subtractive_ix():
    assert roman_to_int("IX") == 9


def test_subtractive_xl_xc():
    assert roman_to_int("XL") == 40
    assert roman_to_int("XC") == 90


def test_subtractive_cd_cm():
    assert roman_to_int("CD") == 400
    assert roman_to_int("CM") == 900


def test_combined_subtractive():
    assert roman_to_int("XIV") == 14
    assert roman_to_int("MCMXCIV") == 1994


def test_invalid_character_raises():
    try:
        roman_to_int("ABC")
    except ValueError:
        return
    raise AssertionError("expected ValueError for invalid characters")
